package dev.veltraph.client.combat.slayer.tara;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TaraSoulWhipTest {
    private final UUID player=UUID.randomUUID(),boss=UUID.randomUUID(),plate=UUID.randomUUID(),egg=UUID.randomUUID(),body=UUID.randomUUID();
    private final Object world=new Object(),connection=new Object();
    private TaraSoulWhip.Profile profile(){return new TaraSoulWhip.Profile(new TaraSoulWhip.Tool("Fixture Whip","minecraft:fishing_rod"),new TaraSoulWhip.Tool("Fixture Whip II","minecraft:fishing_rod"),new TaraSoulWhip.Tool("Fixture Bow","minecraft:bow"),3,5,3,100,200,5000,2,5.0,TaraSoulWhip.OutcomeBinding.EXACT_LOADED_BODY_REMOVAL);}
    private TaraSoulWhip.Custody custody(){return new TaraSoulWhip.Custody(player,boss,plate,world,connection,"full components");}
    private TaraSoulWhip.Frame frame(long tick,long now,boolean aim,Set<UUID> bodies,Set<UUID> removed){return new TaraSoulWhip.Frame(custody(),egg,List.copyOf(bodies),removed,true,true,aim,false,tick,now);}
    private TaraSoulWhip begin(){var owner=new TaraSoulWhip();owner.begin(profile(),frame(0,0,false,Set.of(body),Set.of()));return owner;}
    private void throughRelease(TaraSoulWhip owner){assertEquals(TaraSoulWhip.Action.PREPARE_WHIP,owner.tick(frame(3,100,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(4,120,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.PREPARE_BOW,owner.tick(frame(9,200,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.DRAW_BOW,owner.tick(frame(10,210,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.RELEASE_BOW,owner.tick(frame(13,240,true,Set.of(body),Set.of())).action());}
    @Test void actualSourceCallbacksPrepareWhipThenSeparateBow(){var owner=begin();assertEquals(TaraSoulWhip.Phase.WAITING_FOR_EGGS,owner.phase());assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(2,90,true,Set.of(body),Set.of())).action());throughRelease(owner);assertEquals(TaraSoulWhip.Phase.KILLING_EGGS,owner.phase());assertEquals(0,owner.sentUses());}
    @Test void releasePlanCannotAcknowledgeRemoval(){var owner=begin();throughRelease(owner);assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(14,250,true,Set.of(),Set.of(body))).action());assertFalse(owner.complete());}
    @Test void onlySentReleaseThenLoadedExactBodyRemovalCompletes(){var owner=begin();throughRelease(owner);owner.sent(body,240);assertEquals(TaraSoulWhip.Action.CONTINUE,owner.tick(frame(14,250,false,Set.of(),Set.of(body))).action());assertTrue(owner.complete());assertEquals(TaraSoulWhip.Phase.WAITING_FOR_EGGS,owner.phase());assertEquals(1,owner.sentUses());}
    @Test void nativeDrawMustRemainOwnedUntilExplicitReleaseTick(){var owner=begin();owner.tick(frame(3,100,true,Set.of(body),Set.of()));owner.tick(frame(4,120,true,Set.of(body),Set.of()));owner.tick(frame(9,200,true,Set.of(body),Set.of()));assertEquals(TaraSoulWhip.Action.DRAW_BOW,owner.tick(frame(10,210,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(12,230,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(13,240,false,Set.of(body),Set.of())).action());assertEquals(0,owner.sentUses());}
    @Test void missedOutcomeRetriesOnlyWithinExplicitBound(){var owner=begin();throughRelease(owner);owner.sent(body,240);assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(14,439,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.DRAW_BOW,owner.tick(frame(15,440,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.RELEASE_BOW,owner.tick(frame(18,470,true,Set.of(body),Set.of())).action());owner.sent(body,470);assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(19,670,true,Set.of(body),Set.of())).action());assertEquals(2,owner.sentUses());}
    @Test void lostNativeRayAfterRequestCannotRetry(){var owner=begin();throughRelease(owner);owner.sent(body,240);assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(14,250,false,Set.of(body),Set.of())).action());assertEquals(1,owner.sentUses());}
    @Test void foreignOrNewBodiesCannotBecomeTheNextTarget(){var owner=begin();assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(3,100,true,Set.of(body,UUID.randomUUID()),Set.of())).action());assertEquals(0,owner.sentUses());}
    @Test void nativeContextReplacementAndLoadoutMutationAreTerminal(){for(int changed=0;changed<3;changed++){var owner=begin();var key=new TaraSoulWhip.Custody(player,boss,plate,changed==0?new Object():world,changed==1?new Object():connection,changed==2?"modified components":"full components");assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(new TaraSoulWhip.Frame(key,egg,List.of(body),Set.of(),true,true,true,false,3,100)).action());assertEquals(0,owner.sentUses());}}
    @Test void ownershipChunkAndSafetyFailuresHaveNoUse(){for(int missing=0;missing<3;missing++){var owner=begin();assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(new TaraSoulWhip.Frame(custody(),egg,List.of(body),Set.of(),missing!=0,missing!=1,true,missing==2,3,100)).action());assertEquals(0,owner.sentUses());}}
    @Test void clockRegressionAndExplicitDeadlineStop(){var owner=begin();owner.tick(frame(3,100,false,Set.of(body),Set.of()));assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(4,99,true,Set.of(body),Set.of())).action());owner=begin();assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(100,5000,true,Set.of(body),Set.of())).action());}
    @Test void unresolvedNamesTimingAndOutcomeHaveNoDefaults(){assertThrows(IllegalArgumentException.class,()->new TaraSoulWhip.Tool("","minecraft:fishing_rod"));assertThrows(IllegalArgumentException.class,()->new TaraSoulWhip.Profile(profile().primary(),profile().fallback(),profile().bow(),8,5,3,100,200,5000,2,5,profile().outcomeBinding()));assertThrows(IllegalArgumentException.class,()->new TaraSoulWhip.Profile(profile().primary(),profile().fallback(),profile().bow(),3,4,3,100,200,5000,2,5,profile().outcomeBinding()));assertThrows(NullPointerException.class,()->new TaraSoulWhip.Profile(profile().primary(),profile().fallback(),profile().bow(),3,5,3,100,200,5000,2,5,null));}
    @Test void groupsUseSourceTruncationMedianAndAimMetadata(){UUID a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID();var group=TaraEggGroups.plan(0,10,0,List.of(new TaraEggGroups.Stand(a,-.19,11,.14),new TaraEggGroups.Stand(b,-.11,12,.19),new TaraEggGroups.Stand(c,5.01,11,0)));assertEquals(1,group.size());var g=group.getFirst();assertEquals(b,g.median());assertEquals(-.15,g.centerX(),1e-9);assertEquals(.165,g.centerZ(),1e-9);assertEquals(11.45,g.minY(),1e-9);assertEquals(13.35,g.maxY(),1e-9);assertEquals(Set.of(a,b),Set.copyOf(g.members()));}
    @Test void missingLoadedProofCannotAcknowledgeEvenASentRelease(){var owner=begin();throughRelease(owner);owner.sent(body,240);assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(new TaraSoulWhip.Frame(custody(),egg,List.of(),Set.of(body),true,false,false,false,14,250)).action());assertFalse(owner.complete());}
    @Test void eachBodyNeedsItsOwnPrecedingSentRelease(){UUID second=UUID.randomUUID();var owner=new TaraSoulWhip();owner.begin(profile(),new TaraSoulWhip.Frame(custody(),egg,List.of(body,second),Set.of(),true,true,false,false,0,0));assertEquals(TaraSoulWhip.Action.FAIL,owner.tick(frame(14,250,true,Set.of(),Set.of(body,second))).action());assertFalse(owner.complete());}
    @Test void stopInvalidatesAlreadyPlannedRelease(){var owner=begin();throughRelease(owner);owner.stop("Manual stop");owner.sent(body,240);assertEquals(0,owner.sentUses());assertTrue(owner.failed());}
    @Test void ownedWaitingCallbackHandoffSchedulesOnlySeparateBowCallback(){var owner=new TaraSoulWhip();owner.beginAfterOwnedWhip(profile(),frame(0,0,false,Set.of(body),Set.of()));assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(1,100,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Phase.KILLING_EGGS,owner.phase());assertEquals(TaraSoulWhip.Action.WAIT,owner.tick(frame(5,200,true,Set.of(body),Set.of())).action());assertEquals(TaraSoulWhip.Action.PREPARE_BOW,owner.tick(frame(6,250,true,Set.of(body),Set.of())).action());}
}
